module LPDensityTest

using Test
using KernelSmoothing
using KernelSmoothing: _cjmG
using Distributions: Normal, Exponential, quantile as nquantile, pdf as npdf
using LinearAlgebra: diag, eigvals, Symmetric
using Random: MersenneTwister

# reference values from lpdensity 3.0.1, generated by data/lpdensity_golden.R
include(joinpath(@__DIR__, "data", "lpdensity_golden.jl"))

const I = 1:500
const XN = round.(nquantile.(Normal(), mod.(I .* 0.6180339887498949, 1)) .+ 0.3 .* sin.(I .^ 2); digits = 2)
const XE = -log.(1 .- mod.(I .* 0.7548776662466927, 1))
const W = 1.0 .+ mod.(I, 3)
const K = Dict("triangular" => TriangularKernel(), "epanechnikov" => EpanechnikovKernel(), "uniform" => UniformKernel())
const SELECTION = Dict("mse-rot" => NormalReference(), "mse-dpi" => MSEOptimal(), "imse-dpi" => IMSEOptimal(grid = :points))

@testset "agrees with lpdensity" begin
  for c in LPDENSITY
    x = c.data == :xn ? XN : XE
    selected = !isempty(c.selection)
    m = fit(LocalPolynomialDensity, x; weights = c.weighted ? W : nothing, points = c.grid, degree = c.p,
            derivative = c.v - 1, kernel = K[c.kernel], bandwidth = selected ? SELECTION[c.selection] : c.bw[1],
            minobs = selected ? c.p + 21 : 0, compat = true)
    # R integrates the kernel constants numerically, to about 1e-7 for the triangular kernel,
    # which the minimizations of the plug-in rules can amplify to 1e-5
    tol = selected ? (c.kernel == "triangular" ? 1e-4 : 1e-6) : 1e-10
    @test all(isapprox.(m.h, c.bw; rtol = tol))
    @test m.nwindow == c.nh
    @test m.nunique == c.nhu
    @test all(isapprox.(m.estimate, c.f_p; rtol = tol))
    @test all(isapprox.(m.estimate_bc, c.f_q; rtol = tol))
    @test all(isapprox.(m.se, c.se_p; rtol = tol))
    @test all(isapprox.(m.se_rbc, c.se_q; rtol = tol))
    @test vcov(m) ≈ c.cov_p rtol = tol
  end
end

@testset "boundary adaptivity" begin
  # an exponential density: the estimate at the boundary 0 is consistent, unlike a KDE
  x = rand(MersenneTwister(1), Exponential(), 20_000)
  m = fit(LocalPolynomialDensity, x; points = [0.0, 0.5, 1.0], bandwidth = 0.3)
  @test m.estimate ≈ npdf.(Exponential(), [0.0, 0.5, 1.0]) rtol = 0.05
  f = fit(KDE, x; bandwidth = 0.3)
  @test pdf(f, 0.0) < 0.7   # a kernel density estimate loses about half the mass at the boundary
  # the bias-corrected estimate of order p + 1 reproduces a density that is a polynomial of order p + 1
  # on the window: the uniform density, where the distribution function is linear
  u = collect(range(0, 1; length = 2001))
  mu = fit(LocalPolynomialDensity, u; points = [0.0, 0.5, 1.0], bandwidth = 0.2, minobs = 0)
  @test mu.estimate ≈ [1, 1, 1] rtol = 1e-3
  @test mu.estimate_bc ≈ [1, 1, 1] rtol = 1e-3
end

@testset "plug-in bandwidths" begin
  pts = [0.0, 0.5, 2.0]
  m = fit(LocalPolynomialDensity, XE; points = pts)
  @test m.selection.rule == MSEOptimal()
  @test keys(m.selection.details.pilots) == (:h1, :hp1, :hp2)
  # at a single point, the integrated rule is the pointwise one
  @test fit(LocalPolynomialDensity, XE; points = [0.5], bandwidth = IMSEOptimal(grid = :points)).h ≈
        fit(LocalPolynomialDensity, XE; points = [0.5]).h rtol = 1e-12
  # the standardization makes the rules equivariant under scaling
  @test fit(LocalPolynomialDensity, 3 .* XE; points = 3 .* pts).h ≈ 3 .* m.h rtol = 1e-8
  mi = fit(LocalPolynomialDensity, XE; points = pts, bandwidth = IMSEOptimal(grid = 10))
  @test length(mi.selection.details.grid) == 10 && all(==(mi.h[1]), mi.h)
  # in the tail of a small sample, the floor of minobs observations and distinct values decides
  x = XE[1:60]
  ms = fit(LocalPolynomialDensity, x; points = [0.5, 3.0])
  d = SmoothingData(x)
  @test ms.floored[2] && ms.h[2] == max(knn_distance(d, 3.0, 23), knn_distance(d, 3.0, 23; distinct = true))
  # with five distinct values the pilot fits are singular, and the rules fall back on the floors
  y = repeat(1.0:5.0, 20)
  @test fit(LocalPolynomialDensity, y; points = [3.0]).h == [2.0]
  @test fit(LocalPolynomialDensity, y; points = [3.0], bandwidth = IMSEOptimal(grid = :points)).h == [2.0]
  # lpdensity's squared bias (B₁ + a B₂)² vanishes where the estimated terms have opposite
  # signs: on this exponential sample it chooses 5.1 at the boundary, the guarded rule 0.64
  xc = -log.(1 .- mod.((1:2000) .* 0.5698402909980532, 1))
  m0 = fit(LocalPolynomialDensity, xc; points = [0.0, 0.2, 0.5], compat = true)
  m1 = fit(LocalPolynomialDensity, xc; points = [0.0, 0.2, 0.5])
  @test m0.h[1] > 4 && m1.h[1] < 1
  @test all(m1.h .<= m0.h)   # a larger bias bound gives smaller bandwidths
  @test fit(LocalPolynomialDensity, xc; points = [0.0, 0.2, 0.5], bandwidth = IMSEOptimal(grid = :points)).h[1] <=
        fit(LocalPolynomialDensity, xc; points = [0.0, 0.2, 0.5], bandwidth = IMSEOptimal(grid = :points), compat = true).h[1]
  @test_throws ArgumentError fit(LocalPolynomialDensity, XE; bandwidth = MSEOptimal(regularization = 2))
  @test_throws ArgumentError fit(LocalPolynomialDensity, XE; bandwidth = IMSEOptimal(interior = true))
  @test_throws ArgumentError fit(LocalPolynomialDensity, XE; bandwidth = CoverageOptimal())
end

@testset "kernel constants" begin
  # G of lpdensity for the triangular kernel, exactly (R integrates numerically)
  G = _cjmG(TriangularKernel(), 2)
  @test G ≈ [-7/30 1/12 -0.053174603174603174; 1/12 0.020634920634920634 1/72; -0.053174603174603174 1/72 -0.00992063492063492] rtol = 1e-12
  @test G ≈ G'
end

@testset "interface" begin
  m = fit(LocalPolynomialDensity, XN)
  @test length(m.points) == 19 && m.points[1] ≈ nquantile(XN, 0.05)
  @test m.selection.rule == MSEOptimal()
  C = vcov(m; method = RobustBiasCorrected())
  @test sqrt.(diag(C)) ≈ m.se_rbc rtol = 1e-10
  @test minimum(eigvals(Symmetric(C))) >= -1e-12 * maximum(diag(C))
  @test C == C'
  b = confband(m; rng = MersenneTwister(2))
  @test all(b.lower .< m.estimate_bc .< b.upper) && b.critical > 1.96
  t = coeftable(m)
  @test t.estimate == m.estimate && t.upper_rbc == confint(m)[:, 2]
  @test coef(m) == m.estimate && stderror(m; method = RobustBiasCorrected()) == m.se_rbc
  @test nobs(m) == 500 && bandwidth(m) == m.h
  @test occursin("Local polynomial density", sprint(show, MIME("text/plain"), m))
  @test occursin("LocalPolynomialDensity", sprint(show, m))
  @test_throws ArgumentError fit(LocalPolynomialDensity, XN; degree = 1, derivative = 1)
  @test_throws ArgumentError fit(LocalPolynomialDensity, XN; kernel = GaussianKernel(), bandwidth = 0.5)
  @test_throws ArgumentError fit(LocalPolynomialDensity, XN; bandwidth = SheatherJones())
  @test_throws ArgumentError confint(m; method = Honest(1.0))
  @test_throws ArgumentError fit(LocalPolynomialDensity, fill(2.0, 50); bandwidth = NormalReference())
  # nothing selects the default, as in the other fits; kernels must not be negative
  @test fit(LocalPolynomialDensity, XN; bandwidth = nothing).h == m.h
  @test_throws ArgumentError fit(LocalPolynomialDensity, XN; kernel = derivative(BiweightKernel()), bandwidth = 0.5)
  @test_throws ArgumentError fit(LocalPolynomialDensity, fill(2.0, 50))
end

@testset "integrated bandwidths over a grid" begin
  # the floors and caps of IMSEOptimal belong to the evaluation points: with a grid
  # between the extremes, the floor at the largest observation of an exponential
  # sample used to set the bandwidth, 4.35 against 0.6 for grid = :points
  e = -log.(1 .- mod.((1:2000) .* 0.7548776662466927, 1))
  pts = [0.25, 1.0, 2.0]
  mi = fit(LocalPolynomialDensity, e; points = pts, bandwidth = IMSEOptimal())
  mp = fit(LocalPolynomialDensity, e; points = pts, bandwidth = IMSEOptimal(grid = :points))
  @test mi.h[1] < 2mp.h[1]
  @test all(abs.(mi.estimate .- exp.(-pts)) .< 0.05)
  # prepared data with responses
  @test fit(LocalPolynomialDensity, SmoothingData(e, sin.(e)); points = pts).h == fit(LocalPolynomialDensity, e; points = pts).h
end

@testset "identification" begin
  # heaped data: within one of 10.25 only the values 10 and 11 have positive weight, too
  # few for fits of orders 2 and 3, whose singular Gram matrices used to factor with
  # rounding into estimates far off (lpdensity returns NA)
  x = round.(10 .+ 3 .* sin.(1:2000) .* sqrt.(mod.((1:2000) .* 0.618, 1)))
  m = fit(LocalPolynomialDensity, x; points = [9.1, 10.25, 12.6], bandwidth = 1.0, minobs = 0)
  @test all(isnan, m.estimate) && all(isnan, m.estimate_bc) && m.nunique == [2, 2, 2]
  # with three distinct values the fit of order 2 exists and its bias correction does not
  m = fit(LocalPolynomialDensity, x; points = [10.0], bandwidth = 1.5, minobs = 0)
  @test isfinite(m.estimate[1]) && isnan(m.estimate_bc[1])
  # vcov and bands leave out the points without an estimate
  r = Float64.(repeat(1:5, 20))
  m = fit(LocalPolynomialDensity, r; points = [1.5, 3.0], bandwidth = [3.0, 1.2], minobs = 0)
  @test isfinite(m.estimate_bc[1]) && isnan(m.estimate_bc[2])
  C = vcov(m; method = RobustBiasCorrected())
  @test isfinite(C[1, 1]) && C[1, 1] ≈ m.se_rbc[1]^2 && all(isnan, C[2, :])
  b = confband(m; rng = MersenneTwister(1))
  @test isfinite(b.lower[1]) && isnan(b.lower[2])
end

@testset "covariances over the windows" begin
  # with many distinct values the covariances are sums over the windows, which agree
  # with the product of the dense matrix of influence values
  # (20000 distinct values: windows from 14 points on, the dense product up to 13)
  x = [nquantile(Normal(), mod(0.6180339887498949i, 1)) for i in 1:20000]
  pts = collect(range(-2, 2; length = 15))
  m15 = fit(LocalPolynomialDensity, x; points = pts, bandwidth = 0.5)
  m13 = fit(LocalPolynomialDensity, x; points = pts[1:13], bandwidth = 0.5)
  for method in (Conventional(), RobustBiasCorrected())
    V = vcov(m15; method)
    @test diag(V) ≈ stderror(m15; method) .^ 2 rtol = 1e-12
    @test V == V' && minimum(eigvals(Symmetric(V))) > -1e-12 * maximum(diag(V))
    @test V[1:13, 1:13] ≈ vcov(m13; method) rtol = 1e-12
  end
end

end
